import{_ as t,c as e,o as r,b2 as d}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"C7DatePicker（C7 日期选择器）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-c7-datepicker-design.md","filePath":"superpowers/specs/2026-05-07-c7-datepicker-design.md"}'),n={name:"superpowers/specs/2026-05-07-c7-datepicker-design.md"};function s(c,o,g,a,l,i){return r(),e("div",null,[...o[0]||(o[0]=[d('<h1 id="c7datepicker-c7-日期选择器-设计说明" tabindex="-1">C7DatePicker（C7 日期选择器）设计说明 <a class="header-anchor vp-link" href="#c7datepicker-c7-日期选择器-设计说明" aria-label="Permalink to &quot;C7DatePicker（C7 日期选择器）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-07<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与确认）<br><strong>依据</strong>：<code>原始需求/前端/C7日期选择器.md</code> + Q&amp;A：<strong>1:B 2:C 3:B 4:A 5:A 6:C 7:B</strong>；实现结构：<strong>路线Ⅰ</strong>（薄封装）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>Element Plus <strong><code>ElDatePicker</code></strong> 在不同 <strong><code>type</code></strong> 下默认 <strong><code>format</code> / <code>value-format</code></strong> 不统一；范围选择时业务常需 <strong>单字符串存储</strong>（如 <code>2024-01-01,2024-12-31</code>），亦需可选 <strong>数组输出</strong>。目标：提供 <strong><code>C7DatePicker</code></strong>，在 <strong><code>ElDatePicker</code></strong> 上完成 <strong>type → 默认格式映射</strong>、<strong>范围值合并/拆分</strong>、<strong><code>update:modelValue</code> 与 <code>change</code> / <code>blur</code> / <code>focus</code> 透传</strong>。</p><hr><h2 id="_2-组件边界与对外-api" tabindex="-1">2. 组件边界与对外 API <a class="header-anchor vp-link" href="#_2-组件边界与对外-api" aria-label="Permalink to &quot;2. 组件边界与对外 API&quot;">​</a></h2><h3 id="_2-1-命名与注册" tabindex="-1">2.1 命名与注册 <a class="header-anchor vp-link" href="#_2-1-命名与注册" aria-label="Permalink to &quot;2.1 命名与注册&quot;">​</a></h3><ul><li>组件名：<strong><code>C7DatePicker</code></strong></li><li>位置：<code>quick-ui/src/packages/C7DatePicker/index.vue</code>（与其它 C7 包一致）</li><li>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中注册并导出。</li></ul><h3 id="_2-2-根节点与属性透传-路线i" tabindex="-1">2.2 根节点与属性透传（路线Ⅰ） <a class="header-anchor vp-link" href="#_2-2-根节点与属性透传-路线i" aria-label="Permalink to &quot;2.2 根节点与属性透传（路线Ⅰ）&quot;">​</a></h3><ul><li>根节点为 <strong><code>ElDatePicker</code></strong>。</li><li><strong><code>defineOptions({ name: &#39;C7DatePicker&#39;, inheritAttrs: false })</code></strong></li><li>根 <strong><code>ElDatePicker</code> 上使用 <code>v-bind=&quot;$attrs&quot;</code></strong><br> 文档说明：<strong>除下文「显式 props」外，其余属性与 Element Plus <code>el-date-picker</code> 一致</strong>（如 <strong><code>type</code></strong>、<strong><code>disabled</code></strong>、<strong><code>placeholder</code></strong>、<strong><code>rangeSeparator</code></strong>（<strong>仅</strong>面板展示「起—止」文案）、<strong><code>shortcuts</code></strong> 等）。</li></ul><h3 id="_2-3-显式-props-不占-attrs" tabindex="-1">2.3 显式 props（不占 attrs） <a class="header-anchor vp-link" href="#_2-3-显式-props-不占-attrs" aria-label="Permalink to &quot;2.3 显式 props（不占 attrs）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>Prop</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>rangeMerge</code></strong></td><td><code>boolean</code></td><td><strong><code>false</code></strong>（<strong>Q1:B</strong>）</td><td>范围类 <strong><code>type</code></strong> 下：为 <strong><code>true</code></strong> 时，对外 <strong><code>modelValue</code></strong> 为 <strong>单字符串</strong>（两段值用 <strong><code>mergeDelimiter</code></strong> 连接）；为 <strong><code>false</code></strong> 时，对外与 EP 一致（一般为 <strong>二元数组</strong>，元素形态由 <strong><code>valueFormat</code></strong> / EP 行为决定）。非范围 <strong><code>type</code></strong> 时该 prop <strong>无效果</strong>，实现 <strong>MUST</strong> 在 JSDoc 说明。</td></tr><tr><td><strong><code>mergeDelimiter</code></strong></td><td><code>string</code></td><td><strong><code>&#39;,&#39;</code></strong>（<strong>Q2:C</strong>）</td><td><strong>仅</strong>用于 <strong>存储用合并串</strong> 的拼接与拆分；<strong>与</strong> EP 的 <strong><code>rangeSeparator</code>（UI 文案）</strong> <strong>语义分离</strong>，<strong>不得</strong>用 <strong><code>rangeSeparator</code></strong> 兼作存储分隔符。</td></tr></tbody></table></div><p>调用方若显式传入 <strong><code>format</code></strong> 或 <strong><code>valueFormat</code></strong>（经 attrs 或等价绑定），<strong>MUST 优先于</strong> 本节内置映射（覆盖映射结果）。</p><h3 id="_2-4-事件" tabindex="-1">2.4 事件 <a class="header-anchor vp-link" href="#_2-4-事件" aria-label="Permalink to &quot;2.4 事件&quot;">​</a></h3><ul><li><strong><code>update:modelValue</code></strong>：载荷为 <strong>归一化后的对外值</strong>（见第 4 节）。</li><li><strong><code>change</code></strong>、<strong><code>blur</code></strong>、<strong><code>focus</code></strong>：<strong>透传</strong> EP；<strong><code>change</code></strong> 载荷 <strong>MUST</strong> 与 <strong>当前对外语义</strong>一致（即与 <strong><code>update:modelValue</code></strong> 将提交的值 <strong>同形态</strong>），须在 JSDoc 写明与 EP 原始 <strong><code>change</code></strong> 在边界场景（如清空）下的对齐方式。</li></ul><hr><h2 id="_3-type-→-默认-format-valueformat-q4-a、q5-a、q6-c" tabindex="-1">3. <code>type</code> → 默认 <code>format</code> / <code>valueFormat</code>（<strong>Q4:A</strong>、<strong>Q5:A</strong>、<strong>Q6:C</strong>） <a class="header-anchor vp-link" href="#_3-type-→-默认-format-valueformat-q4-a、q5-a、q6-c" aria-label="Permalink to &quot;3. `type` → 默认 `format` / `valueFormat`（**Q4:A**、**Q5:A**、**Q6:C**）&quot;">​</a></h2><p>以下映射仅在调用方 <strong>未</strong> 传入对应 <strong><code>format</code> / <code>valueFormat</code></strong> 时注入。字符串格式采用 <strong>dayjs 风格</strong>（与 Element Plus 2.x 常见约定一致）。</p><div class="vp-table"><table><thead><tr><th><code>type</code></th><th>默认 <code>format</code>（展示）</th><th>默认 <code>valueFormat</code>（绑定值）</th></tr></thead><tbody><tr><td><strong><code>date</code></strong></td><td><code>YYYY-MM-DD</code></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><strong><code>daterange</code></strong></td><td><code>YYYY-MM-DD</code></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><strong><code>datetime</code></strong></td><td><code>YYYY-MM-DD HH:mm:ss</code></td><td><code>YYYY-MM-DD HH:mm:ss</code></td></tr><tr><td><strong><code>datetimerange</code></strong></td><td><code>YYYY-MM-DD HH:mm:ss</code></td><td><code>YYYY-MM-DD HH:mm:ss</code></td></tr><tr><td><strong><code>month</code></strong></td><td><code>YYYY-MM</code></td><td><code>YYYY-MM</code></td></tr><tr><td><strong><code>monthrange</code></strong></td><td><code>YYYY-MM</code></td><td><code>YYYY-MM</code></td></tr><tr><td><strong><code>year</code></strong></td><td><code>YYYY</code></td><td><code>YYYY</code></td></tr><tr><td><strong><code>yearrange</code></strong></td><td><code>YYYY</code></td><td><code>YYYY</code></td></tr><tr><td><strong><code>week</code></strong></td><td>与 <strong>EP 文档</strong>中 <strong><code>week</code></strong> 类型推荐展示格式对齐（实现时以当前 <strong>Element Plus</strong> 版本文档为准，在 JSDoc 写死实际字符串）</td><td>与 <strong>EP</strong> 在 <strong><code>value-format</code></strong> 下对 <strong><code>week</code></strong> 的返回值约定对齐（<strong>MUST</strong> 在 JSDoc 写死）</td></tr></tbody></table></div><p><strong>未命中上表</strong>的 <strong><code>type</code></strong>（<strong>Q4:A</strong>）：<strong>不</strong>向 EP 注入 <strong><code>format</code> / <code>valueFormat</code></strong>，完全沿用 <strong>EP 默认</strong>。</p><hr><h2 id="_4-范围值的合并、拆分与脏数据-q2-c、q3-b" tabindex="-1">4. 范围值的合并、拆分与脏数据（<strong>Q2:C</strong>、<strong>Q3:B</strong>） <a class="header-anchor vp-link" href="#_4-范围值的合并、拆分与脏数据-q2-c、q3-b" aria-label="Permalink to &quot;4. 范围值的合并、拆分与脏数据（**Q2:C**、**Q3:B**）&quot;">​</a></h2><h3 id="_4-1-输出-rangemerge" tabindex="-1">4.1 输出（<code>rangeMerge</code>） <a class="header-anchor vp-link" href="#_4-1-输出-rangemerge" aria-label="Permalink to &quot;4.1 输出（`rangeMerge`）&quot;">​</a></h3><ul><li><strong><code>rangeMerge === true</code></strong>：对外 <strong><code>modelValue</code></strong> 为 <strong><code>string</code></strong>，形如 <strong><code>start + mergeDelimiter + end</code></strong>（两段均为已按 <strong><code>valueFormat</code></strong> 格式化后的字符串；若 EP 在某种配置下返回 <code>null</code> 空一端，<strong>MUST</strong> 在 JSDoc 定义拼接规则，建议空端用空串且仍保留分隔符或整体 <code>&#39;&#39;</code>，<strong>二选一写死</strong>）。</li><li><strong><code>rangeMerge === false</code></strong>：不合并；对外为 <strong>EP 原生范围值</strong>（通常为长度 2 的数组）。</li></ul><h3 id="_4-2-输入-回显" tabindex="-1">4.2 输入（回显） <a class="header-anchor vp-link" href="#_4-2-输入-回显" aria-label="Permalink to &quot;4.2 输入（回显）&quot;">​</a></h3><ul><li><strong><code>daterange</code>（及同类范围 type）</strong> 下，若父级传入 <strong>单字符串</strong> 且包含 <strong><code>mergeDelimiter</code></strong>（或当 <strong><code>mergeDelimiter</code> 为默认逗号</strong> 时，兼容 <strong><code>,</code></strong>），<strong>MUST</strong> 拆分为 <strong>EP 可接受的内部数组</strong> 以正确回显并可编辑（对齐原始需求验收：<strong><code>&quot;a,b&quot;</code></strong>）。</li><li>拆分后 <strong>无法解析为合法范围</strong>（非法日期、缺一段、多于两段等）（<strong>Q3:B</strong>）：对外可视为 <strong>空范围</strong>；内部归一为 <strong><code>null</code></strong> 或 EP 接受的清空形态；<strong><code>console.warn</code></strong> 一次（文案含原始串摘要即可），<strong>不</strong>向父组件抛专用错误事件。</li></ul><h3 id="_4-3-mergedelimiter-约束" tabindex="-1">4.3 <code>mergeDelimiter</code> 约束 <a class="header-anchor vp-link" href="#_4-3-mergedelimiter-约束" aria-label="Permalink to &quot;4.3 `mergeDelimiter` 约束&quot;">​</a></h3><ul><li><strong>MUST NOT</strong> 为空字符串（实现可在 <strong>JSDoc</strong> 声明非法时回退 <strong><code>&#39;,&#39;</code></strong> 或拒绝更新，<strong>二选一写死</strong>）。</li></ul><hr><h2 id="_5-方案结论-实现结构" tabindex="-1">5. 方案结论（实现结构） <a class="header-anchor vp-link" href="#_5-方案结论-实现结构" aria-label="Permalink to &quot;5. 方案结论（实现结构）&quot;">​</a></h2><ul><li><strong>路线Ⅰ</strong>：单文件 <strong><code>C7DatePicker/index.vue</code></strong> 为主；<strong><code>modelValue</code> / <code>update:modelValue</code></strong> 与 EP 之间做 <strong>归一化/反归一化</strong>；<strong>映射表</strong>可为模块内常量或同目录 <strong><code>defaults.ts</code></strong>（若单文件过长再抽离）。</li></ul><hr><h2 id="_6-测试与验收" tabindex="-1">6. 测试与验收 <a class="header-anchor vp-link" href="#_6-测试与验收" aria-label="Permalink to &quot;6. 测试与验收&quot;">​</a></h2><ul><li><strong><code>daterange</code></strong> + <strong><code>rangeMerge=false</code></strong>：外部 <strong><code>&quot;2024-01-01,2024-12-31&quot;</code></strong>（或按 <strong><code>mergeDelimiter</code> 自定义</strong>）可 <strong>回显</strong> 并可编辑；输出为 <strong>数组</strong>。</li><li><strong><code>daterange</code></strong> + <strong><code>rangeMerge=true</code></strong>：选择范围后对外为 <strong>单字符串</strong>，分隔符为 <strong><code>mergeDelimiter</code></strong>。</li><li><strong><code>format</code>/<code>valueFormat</code> 显式传入</strong>：<strong>覆盖</strong> 内置映射。</li><li><strong>未映射 <code>type</code></strong>：<strong>不</strong>注入默认格式，行为与裸 <strong><code>ElDatePicker</code></strong> 一致。</li><li><strong>非法合并串</strong>：归空 + <strong><code>console.warn</code></strong>（<strong>Q3:B</strong>）。</li><li><strong><code>change</code> / <code>blur</code> / <code>focus</code></strong>：可触发且与 EP 文档不冲突。</li></ul><hr><h2 id="_7-文档与-openspec-q7-b" tabindex="-1">7. 文档与 OpenSpec（<strong>Q7:B</strong>） <a class="header-anchor vp-link" href="#_7-文档与-openspec-q7-b" aria-label="Permalink to &quot;7. 文档与 OpenSpec（**Q7:B**）&quot;">​</a></h2><ul><li>本文件：<strong><code>docs/superpowers/specs/2026-05-07-c7-datepicker-design.md</code></strong></li><li>变更跟踪：<strong><code>openspec/changes/ui-c7-datepicker/</code></strong>（<strong><code>proposal.md</code> / <code>design.md</code> / <code>tasks.md</code> / <code>specs/ui-c7-datepicker/spec.md</code></strong>）</li><li>实现阶段：按需补 <strong><code>docs/docs/frontend/components/通用组件/c7-datepicker.md</code></strong> 与 <strong>Dev 演示</strong>。</li></ul><hr><h2 id="_8-澄清记录-q-a" tabindex="-1">8. 澄清记录（Q&amp;A） <a class="header-anchor vp-link" href="#_8-澄清记录-q-a" aria-label="Permalink to &quot;8. 澄清记录（Q&amp;A）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>题号</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td><strong><code>rangeMerge</code> 默认 <code>false</code></strong>，范围默认对外 <strong>数组</strong>（与 EP 一致）。</td></tr><tr><td>2</td><td><strong>存储分隔符</strong>：<strong><code>mergeDelimiter</code>（默认 <code>,</code>）</strong>；<strong><code>rangeSeparator</code> 仅 UI</strong>，不与存储混用。</td></tr><tr><td>3</td><td><strong>非法合并串</strong>：<strong><code>null</code>/空范围 + <code>console.warn</code></strong>。</td></tr><tr><td>4</td><td><strong>未命中映射的 <code>type</code></strong>：<strong>不注入</strong> <code>format</code>/<code>valueFormat</code>，用 EP 默认。</td></tr><tr><td>5</td><td><strong><code>datetime</code> / <code>datetimerange</code></strong> 默认 <strong><code>valueFormat</code>：<code>YYYY-MM-DD HH:mm:ss</code></strong>（及对应 <code>format</code>）。</td></tr><tr><td>6</td><td>映射表含 <strong>常见 type + <code>week</code></strong>。</td></tr><tr><td>7</td><td><strong>superpowers 设计说明 + OpenSpec 变更</strong> <code>ui-c7-datepicker</code>。</td></tr><tr><td>结构</td><td><strong>路线Ⅰ</strong>：薄封装，根 <strong><code>ElDatePicker</code></strong> + <strong><code>modelValue</code> 归一化</strong>。</td></tr></tbody></table></div><hr><h2 id="_9-自检说明-定稿前已核对" tabindex="-1">9. 自检说明（定稿前已核对） <a class="header-anchor vp-link" href="#_9-自检说明-定稿前已核对" aria-label="Permalink to &quot;9. 自检说明（定稿前已核对）&quot;">​</a></h2><ul><li><strong>无 TBD</strong>：<strong><code>week</code></strong> 的具体格式字符串在实现时以 <strong>EP 版本文档</strong>为准并在 JSDoc 写死。</li><li><strong>一致性</strong>：<strong><code>rangeSeparator</code></strong> 与 <strong><code>mergeDelimiter</code></strong> 职责分离；<strong><code>change</code></strong> 与对外值形态一致。</li><li><strong>范围</strong>：单组件 + 注册导出；不修改 <strong>EP 源码</strong>。</li><li><strong>歧义</strong>：<strong>非法串</strong>不抛业务事件，仅 <strong>warn</strong>；<strong><code>rangeMerge</code> 在非范围 type</strong> 上无效并已说明。</li></ul>',44)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
